  rawCenterY: number;
  labelLineEndX: number;
  labelLineEndY: number;
  labelSide: 'left' | 'right';
  /** Danh sách các điểm neo nằm rải rác sát biên giới tỉnh (tính theo độ lệch dx, dy từ tâm tỉnh trên màn hình) để đặt Avatar không che vùng trung tâm */
