function computeBorderAnchorsFromPath(
  primaryPath: string,
  rawCenterX: number,
  rawCenterY: number,
  targetCount = 24
): Array<{ dx: number; dy: number }> {
  const regex = /[-+]?\d*\.?\d+/g;
  const nums = primaryPath.match(regex);
  const rawPts: Array<{ x: number; y: number }> = [];

  if (nums && nums.length >= 6) {
    for (let i = 0; i < nums.length - 1; i += 2) {
      rawPts.push({
        x: parseFloat(nums[i]),
        y: parseFloat(nums[i + 1]),
      });
    }
  }

  if (rawPts.length < 4) {
    // Fallback hình elip quanh biên nếu path quá ngắn
    const fallback: Array<{ dx: number; dy: number }> = [];
    for (let i = 0; i < targetCount; i++) {
      const angle = (i * 2 * Math.PI) / targetCount;
      fallback.push({
        dx: Math.cos(angle) * 18,
        dy: Math.sin(angle) * 15,
      });
    }
    return fallback;
  }

  // Lấy mẫu đều dọc theo chu vi biên giới tỉnh (tại vị trí 76%–84% từ tâm ra sát đường biên)
  const perimeterSampled: Array<{ dx: number; dy: number }> = [];
  for (let i = 0; i < targetCount; i++) {
    const idx = Math.floor((i * rawPts.length) / targetCount) % rawPts.length;
    const pt = rawPts[idx];
    const ratio = i % 2 === 0 ? 0.78 : 0.84;
    const dxScreen = (pt.x - rawCenterX) * MAP_RENDER_SCALE * ratio;
    const dyScreen = (pt.y - rawCenterY) * MAP_RENDER_SCALE * ratio;

    // Đảm bảo khoảng cách tối thiểu từ tâm để không bao giờ đè vào chữ Điểm ở giữa tỉnh
    const dist = Math.hypot(dxScreen, dyScreen);
    const minRadius = 11;
    if (dist < minRadius && dist > 0.01) {
      const boost = minRadius / dist;
      perimeterSampled.push({
        dx: Number((dxScreen * boost).toFixed(2)),
        dy: Number((dyScreen * boost).toFixed(2)),
      });
    } else {
      perimeterSampled.push({
        dx: Number(dxScreen.toFixed(2)),
        dy: Number(dyScreen.toFixed(2)),
      });
    }
  }

  // Sắp xếp xen kẽ (Golden step) để các Avatar đầu tiên rải đều các phía quanh biên giới tỉnh
  const reordered: Array<{ dx: number; dy: number }> = [];
  const visited = new Set<number>();
  const step = 7; // Nguyên tố cùng nhau với 24
  let cur = 0;
  while (reordered.length < perimeterSampled.length) {
    if (!visited.has(cur)) {
      visited.add(cur);
      reordered.push(perimeterSampled[cur]);
    }
    cur = (cur + step) % perimeterSampled.length;
  }

  return reordered;
}

export function buildVietnamProvincePolygons(
  provinces: ProvinceCell[]
): Map<string, ProvinceMapPolygon> {
  const result = new Map<string, ProvinceMapPolygon>();

  for (const prov of provinces) {
    const item = TRACED_PROVINCE_GEOMETRY[prov.id];
    if (!item) continue;

    const screenCx = MAP_RENDER_OFFSET_X + item.centerX * MAP_RENDER_SCALE;
    const screenCy = MAP_RENDER_OFFSET_Y + item.centerY * MAP_RENDER_SCALE;
    const side: 'left' | 'right' = prov.labelSide === 'left' ? 'left' : 'right';
    const offsetX = side === 'left' ? -42 : 42;
    const offsetY = ((prov.code % 3) - 1) * 4;

    result.set(prov.id, {
      id: prov.id,
      rawPrimaryPath: item.primaryPath,
      rawAllPaths: item.allPaths,
      centerX: screenCx,
      centerY: screenCy,
      rawCenterX: item.centerX,
      rawCenterY: item.centerY,
      labelLineEndX: screenCx + offsetX,
      labelLineEndY: screenCy + offsetY,
      labelSide: side,
      borderAnchors: computeBorderAnchorsFromPath(
        item.primaryPath,
        item.centerX,
        item.centerY,
        24
      ),
    });
  }

  return result;
}
